contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes amount to send to fallback, plus a withdrawAmount to attempt withdrawal
    function run(uint sendAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance to send");

        // read before-values
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // As owner (InvMutTest deployed c), calling fallback by sending Ether
        c.f{value: sendAmount}("");

        // read after-values
        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Now, attempt to call withdraw from this contract (which is owner) and record whether it reverts
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // General rule: sending Ether via fallback as owner increases depositsCount by exactly 1
        // and increases contract balance by exactly sendAmount; also, a withdraw that succeeds must not make depositsCount decrease.
        assert(
            afterCount == beforeCount + 1
            && afterBalance == beforeBalance + sendAmount
            && (withdrewReverted || c.depositsCount() >= afterCount)
        );
    }

    // allow receiving ETH if withdraw transfers here
    receive() external payable {}
}

