contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that when this contract (the owner) calls withdraw or sendMoney,
    // Ether leaves C and ends up either in this contract or is forwarded; and that
    // a non-owner (simulated by calling via address(1)) would not be able to call.
    // Because the checker runs a single transaction where this contract is msg.sender
    // for calls to c, we assert that withdraw and sendMoney (when called by owner)
    // do not revert and reduce address(c).balance by the requested amount (bounded).

    function run(uint depositAmount, uint withdrawAmount, uint sendAmount, address payable target) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");
        // Deposit Ether into c by triggering fallback via a plain call with value.
        // fallback increments depositsCount and increases address(c).balance.
        c.f{value: depositAmount}();

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Ensure we don't try to withdraw more than the contract holds to avoid revert from transfer
        // but allow any inputs: bound withdrawAmount and sendAmount to beforeBalance
        uint boundWithdraw = withdrawAmount;
        if (boundWithdraw > beforeBalance) boundWithdraw = beforeBalance;
        uint boundSend = sendAmount;
        if (boundSend > beforeBalance) boundSend = beforeBalance;

        // Try owner withdraw (this contract is owner). Catch revert flag.
        bool withdrewReverted;
        try c.withdraw(boundWithdraw) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        uint midBalance = address(c).balance;

        // Try owner sendMoney to target
        bool sendReverted;
        try c.sendMoney(target, boundSend) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule asserted:
        // 1) depositsCount increased by exactly 1 due to our fallback deposit call
        // 2) If withdraw did not revert, then beforeBalance - midBalance == boundWithdraw
        // 3) If sendMoney did not revert, then midBalance - afterBalance == boundSend
        // 4) If either call reverted, the balance did not change because of that call
        assert(
            afterDeposits == beforeDeposits + 1
            && ((withdrewReverted && midBalance == beforeBalance) || (!withdrewReverted && beforeBalance - midBalance == boundWithdraw))
