    // We accept parameters: which function to call (as a bool withdrawAllFlag),
    // an amount to withdraw/send, and an address target for sendMoney.
    // The function is payable so we can fund c by calling its fallback via sending Ether.
    function run(bool callWithdrawAll, uint amount, address payable target, uint fund) public payable {
        require(address(this).balance >= fund, "not enough balance to fund");
        // Fund contract c by sending Ether which triggers its fallback and increments depositsCount.
        // We send 'fund' from this contract to c. Ensure top-level state-changing calls.
        address(c).call{value: fund}("");

        // Read observable state before the tested call
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted;
        // Make the deciding call: either withdrawAll or withdraw, invoked by this contract (which is owner)
        if (callWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule asserted:
        // - If the call reverted then balance and depositsCount unchanged.
        // - If it did not revert then depositsCount must be unchanged and balance must be <= beforeBalance
        //   and decreased by at most the requested amount (for withdraw) or by at most beforeBalance (for withdrawAll).
        if (reverted) {
            assert(afterBalance == beforeBalance && afterDeposits == beforeDeposits);
        } else {
            // depositsCount should not increase as withdraw/withdrawAll do not call fallback
            // and thus should not increment depositsCount.
            bool depositsUnchanged = (afterDeposits == beforeDeposits);

            // For withdrawAll, amount parameter is ignored; effective decrease <= beforeBalance.
            // For withdraw, the balance decrease should be <= amount.
            uint decreased;
            if (beforeBalance >= afterBalance) {
                decreased = beforeBalance - afterBalance;
            } else {
                // balance increased is unexpected for a successful withdraw; fail the assert
                decreased = type(uint).max;
            }

            bool balanceOk;
            if (callWithdrawAll) {
                // after successful withdrawAll, decreased must be <= beforeBalance (always true if computed above)
                balanceOk = (decreased <= beforeBalance);
            } else {
                balanceOk = (decreased <= amount);
            }

            assert(depositsUnchanged && balanceOk);
        }
    }

    // Allow receiving Ether to fund this test contract externally if needed
    receive() external payable {}
}

