    function run(bool targetIsFallback, address payable extTarget, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // read before-values
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool reverted;

        if (targetIsFallback) {
