            // This call is made by this contract (not the owner of c), so fallback will execute but transfer will succeed.
            // Perform it and catch revert if any.
            try c.f{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Try to call c.sendMoney(extTarget, amount) as this contract (not owner). This should not revert
            // because sendMoney has no checks, but the internal call may or may not cause state changes on c depending
            // on whether extTarget is payable and how call behaves. We catch reverts of the top-level call.
            try c.sendMoney(extTarget, amount) {
