    // - owner remains equal to the pre-call owner
    // - depositsCount does not increase as a result of sendMoney
    // - if the call succeeded, C's balance after the call is <= balance before minus value (i.e., it did not gain funds);
    //   we express this as: postBalance + value >= preBalance (avoids underflow inside assert)

    function run(address target, uint value) public payable {
        require(true);

        // ensure this contract has enough balance if we plan to send value through C (sendMoney is initiated by owner and uses C's funds,
        // but our call might require this contract to hold Ether for other interactions; still, c.sendMoney uses C's own balance,
        // so no need to fund c here. However to be safe for external calls we don't manipulate balances.)

