contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test tries owner-restricted functions from a non-owner caller (this contract).
    // Parameters:
    //  - sendValue: amount of Ether (if any) to send to c via its fallback by invoking a low-level call to trigger deposit
    //  - callValue: amount of Ether to attempt to transfer from c when calling sendMoney
    function run(uint sendValue, uint callValue) public payable {
        require(address(this).balance >= sendValue, "insufficient balance to seed");
        // Record observable before-values
        address beforeOwner = c.owner();
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;
        uint beforeThis = address(this).balance;

        // Send Ether to c to increase its balance and trigger fallback (which increments depositsCount)
        // We perform this call as a top-level state-changing call on c.
        // Use low-level call to trigger fallback: the contract C has fallback payable which increments depositsCount.
        // We must ensure this contract has enough balance (checked above).
        (bool okSend,) = address(c).call{value: sendValue}("");
        // Try to call owner-only functions withdrawAll, withdraw, and sendMoney and observe reverts.
        bool withdrewAllReverted;
        bool withdrewReverted;
        bool sendMoneyReverted;

        // withdrawAll
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // withdraw with amount callValue
        try c.withdraw(callValue) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // sendMoney attempting to call an arbitrary target (use address(this))
        try c.sendMoney(address(this), callValue) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read after-values
        address afterOwner = c.owner();
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule asserted:
        // - Owner must never change as a result of these calls (owner is only set at deployment in C), and
        // - depositsCount can only have increased by at most 1 due to the explicit fallback call above (okSend indicates whether that succeeded), and
        // - If any of the owner-only calls reverted then C's balance and depositsCount did not decrease as a consequence of that reverting call.
        // We express: owner unchanged, depositsCount >= beforeDeposits and <= beforeDeposits + 1, and if any revert occurred then afterBalance <= beforeBalance (no unexpected increase) and afterThis <= beforeThis + (okSend ? sendValue : 0) + (sendMoneyReverted ? 0 : callValue);

        assert(
            // owner unchanged
            afterOwner == beforeOwner
            // deposits increment only from the fallback call at most by 1
            && afterDeposits >= beforeDeposits
            && afterDeposits <= beforeDeposits + (okSend ? 1 : 0)
            // If any owner-only call reverted, then c's balance did not decrease due to that revert (i.e., it's >= beforeBalance - 0)
            && (
                (withdrewAllReverted || withdrewReverted || sendMoneyReverted)
                ? (afterBalance >= beforeBalance - 0)
                : true
            )
            // The test contract's balance cannot have unexpectedly increased by more than what it legitimately received:
            // It may receive sendValue only if okSend caused fallback (but that sends to c, not to this), and may receive funds via sendMoney only if it succeeded.
            // So afterThis is at most beforeThis + (sendMoney succeeded ? callValue : 0)
            && afterThis <= beforeThis + (sendMoneyReverted ? 0 : callValue)
        );
    }

    receive() external payable {
        // allow receiving Ether when sendMoney calls back
    }
}

