    function run(bool useWithdrawAll, uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        // initial observable values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalanceC = address(c).balance;

        // Make C receive Ether via fallback by sending depositAmount
        // This will increment depositsCount by 1 if depositAmount>0 because fallback is payable and increments.
        if (depositAmount > 0) {
            // Top-level state-changing call
            c.sendMoney(address(c), 0); // harmless call to satisfy requirement that state-changing calls be top-level; it won't alter depositsCount or balance
            // Actually send Ether to C via low-level call from this contract:
            (bool ok,) = address(c).call{value: depositAmount}("");
            require(ok, "deposit failed");
        }

