        uint midDeposits = c.depositsCount();
        uint midBalanceC = address(c).balance;

        // Decide and perform withdraw: either withdrawAll or withdraw(withdrawAmount)
        bool reverted;
        if (useWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
