contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function with inputs: target address and amount to send/withdraw
    function run(address payable target, uint amount) public payable {
        require(true);

        // read observable before-values
        uint beforeBalance = address(c).balance;
        address ownerBefore = c.owner();

        // attempt withdraw: catch whether it reverts
        bool withdrawReverted;
        try c.withdraw{value: 0}(amount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // attempt sendMoney: also catch revert
        bool sendReverted;
        try c.sendMoney{value: 0}(target, amount) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        // attempt withdrawAll
        bool withdrawAllReverted;
        try c.withdrawAll{value: 0}() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // read after-values
        uint afterBalance = address(c).balance;
        address ownerAfter = c.owner();

        // General rule asserted:
        // If any of these three calls succeeded (did not revert), then msg.sender for those calls
        // must have been the owner recorded by C (i.e., this contract must be ownerBefore).
        // Also, whenever a call succeeded, C's balance cannot have increased compared to before
        // (it may have decreased by at most the requested amount for withdraw/sendMoney or by any amount for withdrawAll).
        bool anySucceeded = (!withdrawReverted) || (!sendReverted) || (!withdrawAllReverted);

        // If any succeeded, ownerBefore must equal this contract (address(this)) and owner didn't change.
        // Also assert that afterBalance <= beforeBalance (balance never increases as a result of these owner actions).
        assert(
            // if none succeeded, no constraint beyond balance non-increase
            (!anySucceeded && afterBalance <= beforeBalance)
            ||
            // if any succeeded, ownerBefore==this and owner unchanged and balance didn't increase
            (anySucceeded && ownerBefore == address(this) && ownerAfter == ownerBefore && afterBalance <= beforeBalance)
        );
    }

    // receive so this test can accept Ether if needed in other variants
    receive() external payable { }
 }
